-- 10_competitive.sql
-- (part A) All staging.competitive_* tables except competitive_geo_* and competitive_project_* (those are in 50_geo_project.sql).
-- Fictional (TEST) data. Ids: competitors c0ffee00-..., products b0000000-0000-4000-8000-0000000000NM, client products 91xx, matchups 9301-9312.
-- Parent tables are inserted before their children; deletes run children first.
BEGIN;

-- own tables, children first
DELETE FROM staging.competitive_stock_series;
DELETE FROM staging.competitive_stock_quote;
DELETE FROM staging.competitive_patent_filing;
DELETE FROM staging.competitive_patent_classification;
DELETE FROM staging.competitive_patent_portfolio;
DELETE FROM staging.competitive_partnership_relationship_detail;
DELETE FROM staging.competitive_partnership_evidence;
DELETE FROM staging.competitive_partnership;
DELETE FROM staging.competitive_product_evaluation_spec;
DELETE FROM staging.competitive_product_evaluation;
DELETE FROM staging.competitive_matchup_source;
DELETE FROM staging.competitive_matchup_advantage;
DELETE FROM staging.competitive_matchup_specification;
DELETE FROM staging.competitive_matchup;
DELETE FROM staging.competitive_product_news;
DELETE FROM staging.competitive_product_program;
DELETE FROM staging.competitive_product_specification;
DELETE FROM staging.competitive_product;
DELETE FROM staging.competitive_competitor_moment_source;
DELETE FROM staging.competitive_competitor_moment_analysis;
DELETE FROM staging.competitive_competitor_moment;
DELETE FROM staging.competitive_signal_evidence;
DELETE FROM staging.competitive_signal_detail;
DELETE FROM staging.competitive_signal;
DELETE FROM staging.competitive_news_article;
DELETE FROM staging.competitive_leader_record;
DELETE FROM staging.competitive_leader;
DELETE FROM staging.competitive_competitor_swot;
DELETE FROM staging.competitive_competitor_location;

-- Where each competitor operates (Profile > Global Locations chips; hover shows type and source).

-- Strengths / weaknesses / opportunities / threats per competitor (stored; hidden on the UI by decision).

-- Leadership cards (Profile > Leaders; click opens experience + education).

-- Experience and education rows of each leader (Profile > Leaders > detail).

-- Company news stories, one row per story (Profile > News; category filter uses the category column).

-- Overview feed cards: one signal per competitor event (Overview feed; sequence_no orders threats first; classification = threat / watch / fav).

-- Drawer text of each signal (opens when a feed card is clicked).

-- At-a-glance facts (evidence_group fact) and key points (key_point) shown in the signal drawer.

-- Competitor Moment cards: one row per competitor move, graded high / watch / opportunity (Competitor Moment page).

-- Deeper analysis per dashboard area for a move (Competitor Moment > Go deeper).

-- Articles reporting each move (Competitor Moment > sources; source_type company / official / news).

-- Competitor product catalogue (Products page: grouped by competitor and category).

-- Specification rows of each competitor product (Products > product detail).

-- Defence programmes a competitor product takes part in (Products > product detail > Programmes).

-- News stories about one product (Products > product detail > News); comparison_reason links a story to a second product.

-- Product Evaluation: one matchup of an Aurora product against a competitor product. edge_score 0-100 (50 = parity) and decision_level 1/2/3 follow prompts/derive.py.

-- Per-spec comparison rows (Product Evaluation > Spec Comparison). gap_value = abs(client - competitor) / mean * 100; better_side is 'equal' under a 3 % gap.

-- Where each side is stronger (Product Evaluation > Advantages); side is client or competitor.

-- Documents a matchup rests on (Product Evaluation > Sources).

-- Older evaluation table (not read by any page; matchups replace it). kssl_product_id is a uuid built from the client product id (00000000-0000-4000-8000-0000000091xx) because client products have bigint ids.

-- Spec rows of the older evaluation table (not read by any page).

-- Partners of each competitor (Partnerships page: graph nodes + cards). relationship_confidence = official / corroborated / single_source.

-- Evidence cards behind a partnership (Partnerships > relationship > evidence cards, numbered).

-- One detail record per evidence card (Partnerships > relationship detail view; selected_card_id is the card it shows).

-- One patent portfolio per competitor (Patents > By rival: counts and notes; empty_message shows when there are no filings).

-- Filing counts per technology field, written once per lens (rival / field) (Patents > By technology field).

-- Individual patent filings (Patents > filing cards). Keyed by publication_number; classification_text equals the category label so the technology lens finds it.

-- Latest share quote per competitor (stored; hidden on the UI by decision). availability_state: available / delayed / unavailable.

-- Share-price series points per range (stored; hidden on the UI). move_news_article_id points to the news story that explains the move.

COMMIT;
