INSERT INTO staging.competitive_signal
  (signal_id, company_id, classification, sequence_no, title, summary, category, event_date, thumbnail_url) VALUES
  ('a6000000-0000-4000-8000-000000000001', 'c0ffee00-0000-4000-8000-000000000001', 'threat', 1, 'Borealis wins NOK 2.1 bn order for 155 mm towed howitzers', 'Borealis secures a Polish order for BH-155 howitzers, the gun that competes head-on with Aurora Gun 155 in export tenders (TEST DATA).', 'Artillery', '2026-10-08', 'https://img.example.com/signals/1.jpg'),
  ('a6000000-0000-4000-8000-000000000002', 'c0ffee00-0000-4000-8000-000000000003', 'threat', 2, 'Halcyon signs export deal for 72 SPH-155 self-propelled guns', 'Halcyon wins a 72-gun Romanian order for the SPH-155, showing it can deliver self-propelled 155 mm guns faster than Aurora can offer a mounted equivalent (TEST DATA).', 'Artillery', '2026-10-11', 'https://img.example.com/signals/2.jpg'),
  ('a6000000-0000-4000-8000-000000000003', 'c0ffee00-0000-4000-8000-000000000005', 'threat', 3, 'Tessera gets MoD fast-track approval for Drone Killer', 'Tessera''s Drone Killer is cleared for fast-track procurement, putting it ahead of Aurora Interceptor Drone in the same domestic counter-UAS requirement (TEST DATA).', 'Unmanned & Counter-UAS', '2026-10-05', 'https://img.example.com/signals/3.jpg'),
  ('a6000000-0000-4000-8000-000000000007', 'c0ffee00-0000-4000-8000-000000000003', 'threat', 4, 'Halcyon doubles K-Shell 155 output to 300,000 rounds a year', 'Halcyon doubles its 155 mm shell capacity, giving it the volume to undercut Aurora Shell 155 on price and lead time in urgent-buy tenders (TEST DATA).', 'Ammunition', '2026-09-05', 'https://img.example.com/signals/7.jpg'),
  ('a6000000-0000-4000-8000-000000000004', 'c0ffee00-0000-4000-8000-000000000002', 'watch', 5, 'Cobalt delivers first 40 Guardian APCs to Saudi customer', 'Cobalt starts deliveries of the Guardian APC to a Gulf customer; no direct Aurora bid is affected yet, but it sets the price point for 8x8 carriers in the region (TEST DATA).', 'Armoured Vehicles', '2026-10-02', 'https://img.example.com/signals/4.jpg'),
  ('a6000000-0000-4000-8000-000000000005', 'c0ffee00-0000-4000-8000-000000000001', 'watch', 6, 'Borealis Smart Shell passes 60 km range trial', 'Borealis proves a 60 km guided 155 mm shell; no tender is lost yet but the benchmark for extended-range shells moves (TEST DATA).', 'Ammunition', '2026-08-19', 'https://img.example.com/signals/5.jpg'),
  ('a6000000-0000-4000-8000-000000000006', 'c0ffee00-0000-4000-8000-000000000004', 'watch', 7, 'Meridian unveils long-range 155 mm shell', 'Meridian shows LR-155 (55 km, 25-year shelf life); a second benchmark competitor in extended-range shells (TEST DATA).', 'Ammunition', '2026-09-03', 'https://img.example.com/signals/6.jpg'),
  ('a6000000-0000-4000-8000-000000000008', 'c0ffee00-0000-4000-8000-000000000002', 'watch', 8, 'Cobalt and Tessera sign counter-drone teaming MoU', 'Two competitors team up on counter-drone systems, which could combine Cobalt''s Swarm Interceptor with Tessera''s local presence (TEST DATA).', 'Unmanned & Counter-UAS', '2026-07-30', 'https://img.example.com/signals/8.jpg'),
  ('a6000000-0000-4000-8000-000000000010', 'c0ffee00-0000-4000-8000-000000000005', 'watch', 9, 'Tessera completes live-fire trial of Vayu missile', 'Tessera''s Vayu medium-range missile passes a live-fire trial; Aurora has no missile product, so the effect is on shared counter-UAS customers (TEST DATA).', 'Missiles & Air Defence', '2026-08-07', 'https://img.example.com/signals/10.jpg'),
  ('a6000000-0000-4000-8000-000000000009', 'c0ffee00-0000-4000-8000-000000000004', 'fav', 10, 'Meridian delays W8 wheeled APC deliveries by two quarters', 'Meridian''s W8 APC deliveries slip two quarters, opening ground for Aurora APC with Gulf and francophone buyers waiting for vehicles (TEST DATA).', 'Armoured Vehicles', '2026-09-28', 'https://img.example.com/signals/9.jpg');
INSERT INTO staging.competitive_signal_detail
  (signal_id, drawer_title, impact_eyebrow, what_article_says, why_it_matters, provenance, source_name, source_url, ask_box_query) VALUES
  ('a6000000-0000-4000-8000-000000000001', 'Borealis wins NOK 2.1 bn Polish order for BH-155 towed howitzers', 'Order won in artillery', 'Borealis Arms (TEST) announced a NOK 2.1 bn contract with the Polish Armament Agency (TEST) for 48 BH-155 155 mm towed howitzers with deliveries from 2027. The company said the order includes a local barrel line.', 'The BH-155 is the direct rival of Aurora Gun 155. A Polish win strengthens Borealis with a NATO customer Aurora has been courting, and the local barrel line lowers Borealis''s price in later tenders.', 'Company announcement; confirmed by trade press (TEST DATA)', 'Borealis Arms newsroom (TEST)', 'https://borealis-arms.example.com/news/bh-155-polish-order', 'How does the Borealis BH-155 order change Aurora Gun 155''s chances in Eastern European tenders?'),
  ('a6000000-0000-4000-8000-000000000002', 'Halcyon signs export deal for 72 SPH-155 self-propelled guns with Romania', 'Export win in artillery', 'Halcyon Land Systems (TEST) said it signed a contract with the Romanian MoD (TEST) for 72 SPH-155 self-propelled guns, with first deliveries within 14 months of signing.', 'Fast delivery is Halcyon''s selling point. The order sits in the market where Aurora Mounted Gun is being offered, and it sets a delivery benchmark Aurora would have to match.', 'Company announcement; single trade-press confirmation (TEST DATA)', 'Halcyon newsroom (TEST)', 'https://halcyon-land.example.com/news/romania-sph-155', 'Which of Aurora''s artillery products compete with the Halcyon SPH-155 in the Romanian market?'),
  ('a6000000-0000-4000-8000-000000000003', 'Tessera receives MoD fast-track approval for the Drone Killer interceptor', 'Domestic approval in counter-UAS', 'Tessera Aerospace (TEST) said the Indian MoD (TEST) approved the Drone Killer interceptor for fast-track procurement under its counter-drone programme.', 'Fast-track status means Tessera can be contracted without a full trial cycle. Aurora Interceptor Drone is still pre-production and could lose the first tranche.', 'Company announcement (TEST DATA)', 'Tessera newsroom (TEST)', 'https://tessera-aero.example.com/news/drone-killer-fast-track', 'Where does Aurora Interceptor Drone stand against the Tessera Drone Killer in the Indian fast-track programme?'),
  ('a6000000-0000-4000-8000-000000000007', 'Halcyon doubles K-Shell 155 annual production to 300,000 rounds', 'Capacity jump in ammunition', 'Sample Army Review reported that Halcyon Land Systems (TEST) has doubled the annual capacity of its K-Shell 155 line to 300,000 rounds after a new filling plant opened.', 'Volume gives Halcyon the shortest lead times in the 155 mm shell market, which is where Aurora Shell 155 competes on price.', 'Trade press report (TEST DATA)', 'Sample Army Review', 'https://news.example.com/halcyon-k-shell-capacity', 'How does Halcyon''s 300,000-round capacity compare to Aurora Shell 155 output and lead time?'),
  ('a6000000-0000-4000-8000-000000000004', 'Cobalt Dynamics delivers first 40 Guardian APCs to Saudi Land Forces', 'Delivery in armoured vehicles', 'Sample Army Review reported the handover of the first 40 Guardian 8x8 armoured personnel carriers to Saudi Land Forces (TEST) under a 200-vehicle contract.', 'Aurora APC is not currently bid in the Gulf, so the effect is indirect: it shows Cobalt''s production rate and the price band for Level 4 8x8 carriers.', 'Trade press report (TEST DATA)', 'Sample Army Review', 'https://news.example.com/cobalt-guardian-delivery', 'Does the Cobalt Guardian APC delivery affect Aurora APC export plans in the Gulf?'),
  ('a6000000-0000-4000-8000-000000000005', 'Borealis Smart Shell 155 passes 60 km range trial', 'Range benchmark in ammunition', 'Borealis Arms (TEST) reported that Smart Shell 155 reached 60 km with 8 m circular error probable in a trial at the Norwegian test range.', 'Guided shells widen the gap to Aurora Shell 155 (36 km, unguided). The effect is indirect until a buyer asks for guided rounds.', 'Company trial report (TEST DATA)', 'Borealis Arms newsroom (TEST)', 'https://borealis-arms.example.com/news/smart-shell-trial', 'What would Aurora need to offer to answer a 60 km guided 155 mm shell?'),
  ('a6000000-0000-4000-8000-000000000006', 'Meridian Ordnance unveils LR-155 long-range 155 mm shell', 'Product launch in ammunition', 'Meridian Ordnance (TEST) unveiled the LR-155 at the Valmont trade show, quoting 55 km range, 30 m CEP and a 25-year shelf life.', 'LR-155 targets the same customers as Aurora Shell 155 and is ahead on every comparable value, though not yet in production.', 'Company press release (TEST DATA)', 'Meridian Ordnance newsroom (TEST)', 'https://meridian-ordnance.example.com/press/lr-155', 'Which export customers are likely to compare Aurora Shell 155 with the Meridian LR-155?'),
  ('a6000000-0000-4000-8000-000000000008', 'Cobalt Dynamics and Tessera Aerospace sign counter-drone teaming MoU', 'Teaming in counter-UAS', 'Example Defence Wire reported that Cobalt Dynamics (TEST) and Tessera Aerospace (TEST) signed a memorandum of understanding to team on counter-drone offers for India.', 'A US-Indian pairing could out-bid Aurora Interceptor Drone on both performance (Cobalt) and local content (Tessera).', 'Trade press report (TEST DATA)', 'Example Defence Wire', 'https://news.example.com/cobalt-tessera-mou', 'How would a Cobalt-Tessera team change Aurora''s counter-UAS bid strategy?'),
  ('a6000000-0000-4000-8000-000000000010', 'Tessera Aerospace completes live-fire trial of the Vayu missile', 'Trial in air defence', 'Sample Army Review reported that Tessera Aerospace (TEST) fired the Vayu missile at a drone target at 22 km in a live-fire trial.', 'Aurora has no air-defence missile; the relevance is the customer overlap and the signal that Tessera is broadening beyond drones.', 'Trade press report (TEST DATA)', 'Sample Army Review', 'https://news.example.com/tessera-vayu-live-fire', 'Which Aurora customers could also buy the Tessera Vayu missile?'),
  ('a6000000-0000-4000-8000-000000000009', 'Meridian Ordnance delays W8 APC deliveries by two quarters', 'Competitor delay in armoured vehicles', 'Test Defence Daily reported that Meridian Ordnance (TEST) will deliver the first W8 wheeled APCs two quarters late because of an armour-supply problem.', 'Buyers waiting for W8 may consider Aurora APC, which is already in series production and has near-identical protection.', 'Trade press report (TEST DATA)', 'Test Defence Daily', 'https://news.example.com/meridian-w8-delay', 'Which W8 customers could Aurora APC target during Meridian''s delay?');
