INSERT INTO staging.competitive_competitor_moment
  (moment_id, competitor_id, company_display, movement_date, category, country_name, countries, region, program_name, title, card_summary, description, what_happened, kssl_analysis, grade, source_label, source_domain, source_url, image_url, display_order) VALUES
  (9402, 'c0ffee00-0000-4000-8000-000000000003', 'Halcyon Land Systems (TEST)', '2026-10-11', 'Artillery', 'Romania', 'Romania, South Korea', 'NATO eastern flank', 'Romanian SPH Buy (TEST)', 'Halcyon signs 72-gun SPH-155 export deal with Romania', 'Halcyon wins a 72-gun Romanian self-propelled gun order.', 'Halcyon Land Systems (TEST) signed an export contract for 72 SPH-155 guns with Romania.', 'Halcyon Land Systems (TEST) signed a contract with the Romanian MoD (TEST) for 72 SPH-155 self-propelled 155 mm guns, with first deliveries within 14 months.', 'Touches Aurora Mounted Gun (TEST) and Aurora Gun 155 (TEST) in the same market. Halcyon sets a delivery-time benchmark Aurora should price against.', 'high', 'Halcyon newsroom (TEST)', 'halcyon-land.example.com', 'https://halcyon-land.example.com/news/romania-sph-155', 'https://img.example.com/moments/9402.jpg', 1),
  (9401, 'c0ffee00-0000-4000-8000-000000000001', 'Borealis Arms (TEST)', '2026-10-08', 'Artillery', 'Poland', 'Poland, Norway', 'Europe', 'Polish Howitzer Modernisation (TEST)', 'Borealis wins NOK 2.1 bn order for 155 mm towed howitzers', 'Borealis wins a Polish order for 48 BH-155 howitzers.', 'Borealis Arms (TEST) won a NOK 2.1 bn Polish contract for BH-155 towed howitzers.', 'The Polish Armament Agency (TEST) signed a NOK 2.1 bn contract with Borealis Arms (TEST) for 48 BH-155 155 mm towed howitzers. Deliveries start in 2027 and the contract includes a barrel line in Poland.', 'Directly touches Aurora Gun 155: the BH-155 is the same class and now has a NATO reference customer. Expect price pressure in Eastern European towed-gun tenders.', 'high', 'Borealis Arms newsroom (TEST)', 'borealis-arms.example.com', 'https://borealis-arms.example.com/news/bh-155-polish-order', 'https://img.example.com/moments/9401.jpg', 2),
  (9403, 'c0ffee00-0000-4000-8000-000000000005', 'Tessera Aerospace (TEST)', '2026-10-05', 'Unmanned & Counter-UAS', 'India', 'India', 'South Asia', 'Indian Counter-Drone Fast Track (TEST)', 'Tessera Drone Killer cleared for MoD fast-track procurement', 'Tessera''s interceptor is approved for fast-track buying.', 'The Indian MoD (TEST) cleared Tessera''s Drone Killer for fast-track procurement.', 'Tessera Aerospace (TEST) announced that the Indian MoD (TEST) approved the Drone Killer interceptor under a counter-drone fast-track programme.', 'Touches Aurora Interceptor Drone (TEST), which is still pre-production. Aurora risks losing the first tranche unless it can show a faster approval path.', 'high', 'Tessera newsroom (TEST)', 'tessera-aero.example.com', 'https://tessera-aero.example.com/news/drone-killer-fast-track', 'https://img.example.com/moments/9403.jpg', 3),
  (9404, 'c0ffee00-0000-4000-8000-000000000002', 'Cobalt Dynamics (TEST)', '2026-10-02', 'Armoured Vehicles', 'Saudi Arabia', 'Saudi Arabia, United States', 'Middle East', 'Gulf APC Fleet (TEST)', 'Cobalt delivers first 40 Guardian APCs', 'First 40 of 200 Guardian APCs handed over to Saudi Land Forces.', 'Cobalt Dynamics (TEST) handed over the first 40 Guardian APCs to Saudi Land Forces (TEST).', 'Cobalt Dynamics (TEST) delivered the first 40 of 200 Guardian 8x8 armoured personnel carriers to Saudi Land Forces (TEST).', 'Indirect for Aurora APC (TEST): not bid in the Gulf, but the delivery sets the price and protection benchmark for 8x8 carriers.', 'watch', 'Sample Army Review', 'news.example.com', 'https://news.example.com/cobalt-guardian-delivery', 'https://img.example.com/moments/9404.jpg', 4),
  (9407, 'c0ffee00-0000-4000-8000-000000000004', 'Meridian Ordnance (TEST)', '2026-09-28', 'Armoured Vehicles', 'United Arab Emirates', 'United Arab Emirates, France', 'Middle East', 'Gulf Wheeled APC (TEST)', 'Meridian delays W8 APC deliveries by two quarters', 'W8 deliveries slip because of an armour-supply problem.', 'Meridian Ordnance (TEST) will deliver the W8 APC two quarters late.', 'Meridian Ordnance (TEST) told customers the first W8 deliveries will be two quarters late because of armour supply.', 'Opens ground for Aurora APC (TEST), which is in series production at Level 3 protection and could offer an earlier delivery slot.', 'opportunity', 'Test Defence Daily', 'news.example.com', 'https://news.example.com/moment-9407', 'https://img.example.com/moments/9407.jpg', 5),
  (9405, 'c0ffee00-0000-4000-8000-000000000001', 'Borealis Arms (TEST)', '2026-09-12', 'Artillery', 'Poland', 'Poland, Norway', 'Europe', 'Borealis Poland Barrel Line (TEST)', 'Borealis opens second 155 mm barrel line in Poland', 'Borealis doubles gun barrel capacity near its Polish customer.', 'Borealis Arms (TEST) opened a second 155 mm barrel line in Gdynia-Test, Poland.', 'Borealis Arms (TEST) opened a second barrel line at its Gdynia-Test plant, doubling capacity for 155 mm gun barrels.', 'Capacity near a major NATO customer lowers Borealis''s delivery risk. Relevant to Aurora Gun 155 (TEST) but indirect until a new tender opens.', 'watch', 'Test Defence Daily', 'news.example.com', 'https://news.example.com/borealis-second-barrel-line', 'https://img.example.com/moments/9405.jpg', 6),
  (9406, 'c0ffee00-0000-4000-8000-000000000004', 'Meridian Ordnance (TEST)', '2026-09-03', 'Ammunition', 'France', 'France', 'Europe', 'French Army LR Shell Evaluation (TEST)', 'Meridian unveils LR-155 long-range shell', '55 km shell with electronic fuze shown at Valmont.', 'Meridian Ordnance (TEST) unveiled the LR-155 155 mm shell with a 55 km range.', 'Meridian Ordnance (TEST) unveiled the LR-155 long-range 155 mm shell at the Valmont trade show, quoting 55 km range and 25-year shelf life.', 'Touches Aurora Shell 155 (TEST): ahead on range, CEP and shelf life, but not yet in production, so a medium-term benchmark.', 'watch', 'Meridian Ordnance newsroom (TEST)', 'meridian-ordnance.example.com', 'https://meridian-ordnance.example.com/press/lr-155', 'https://img.example.com/moments/9406.jpg', 7),
  (9408, 'c0ffee00-0000-4000-8000-000000000003', 'Halcyon Land Systems (TEST)', '2026-08-27', 'Artillery', 'South Korea', 'South Korea', 'Asia-Pacific', NULL, 'Halcyon names new CEO as founder steps back', 'Leadership change at the self-propelled gun maker.', 'Halcyon Land Systems (TEST) appointed a new Chief Executive.', 'Halcyon Land Systems (TEST) announced that its founder-chairman will step back and a new Chief Executive takes over from 1 October.', 'Leadership transitions can slow export decisions at Halcyon; a window for Aurora Gun 155 (TEST) in pending artillery tenders. Low confidence.', 'opportunity', 'Placeholder Business Journal', 'news.example.com', 'https://news.example.com/halcyon-new-ceo', 'https://img.example.com/moments/9408.jpg', 8),
  (9411, 'c0ffee00-0000-4000-8000-000000000001', 'Borealis Arms (TEST)', '2026-08-19', 'Ammunition', 'Norway', 'Norway', 'Europe', 'Smart Shell 155 Development (TEST)', 'Borealis Smart Shell reaches 60 km in range trial', 'Guided 155 mm shell sets a 60 km benchmark.', 'Borealis Arms (TEST) reported a 60 km range and 8 m CEP for Smart Shell 155.', 'Borealis Arms (TEST) published trial results showing Smart Shell 155 reaching 60 km with 8 m circular error probable.', 'Directly touches Aurora Shell 155 (TEST), rated 36 km and unguided. Buyers asking for precision will see Aurora as a generation behind.', 'high', 'Borealis Arms newsroom (TEST)', 'borealis-arms.example.com', 'https://borealis-arms.example.com/news/smart-shell-trial', 'https://img.example.com/moments/9411.jpg', 9),
  (9409, 'c0ffee00-0000-4000-8000-000000000005', 'Tessera Aerospace (TEST)', '2026-08-07', 'Missiles & Air Defence', 'India', 'India', 'South Asia', 'Indian Medium SAM Programme (TEST)', 'Tessera completes Vayu missile live-fire trial', 'Medium-range missile engages a drone target at 22 km.', 'Tessera Aerospace (TEST) completed a live-fire trial of the Vayu missile.', 'Tessera Aerospace (TEST) fired the Vayu missile at a drone target at 22 km in a live-fire trial.', 'No Aurora missile product is touched; relevant for shared counter-UAS customers in India.', 'watch', 'Sample Army Review', 'news.example.com', 'https://news.example.com/tessera-vayu-live-fire', 'https://img.example.com/moments/9409.jpg', 10),
  (9410, 'c0ffee00-0000-4000-8000-000000000002', 'Cobalt Dynamics (TEST)', '2026-07-30', 'Unmanned & Counter-UAS', 'India', 'India, United States', 'South Asia', 'Cobalt-Tessera Counter-Drone Teaming (TEST)', 'Cobalt and Tessera team on counter-drone offers', 'MoU between two competitors for Indian counter-UAS bids.', 'Cobalt Dynamics (TEST) and Tessera Aerospace (TEST) signed a teaming MoU.', 'Cobalt Dynamics (TEST) and Tessera Aerospace (TEST) signed a memorandum of understanding to prepare joint counter-drone offers for India.', 'Touches Aurora Interceptor Drone (TEST): a combined US-Indian offer would compete on performance and local content.', 'watch', 'Example Defence Wire', 'news.example.com', 'https://news.example.com/cobalt-tessera-mou', 'https://img.example.com/moments/9410.jpg', 11),
  (9412, 'c0ffee00-0000-4000-8000-000000000004', 'Meridian Ordnance (TEST)', '2026-06-18', 'Ammunition', 'United Arab Emirates', 'United Arab Emirates, France', 'Middle East', 'Emirates Shell Supply (TEST)', 'Meridian expands Gulf shell supply agreement', 'Larger 155 mm shell volumes to the UAE.', 'Meridian Ordnance (TEST) expanded its shell supply agreement with the UAE.', 'Meridian Ordnance (TEST) agreed an expanded multi-year supply of 155 mm shells to the UAE through its local munitions park.', 'Meridian is entrenched in Gulf ammunition; Aurora Shell 155 (TEST) has little room there short-term.', 'watch', 'Test Defence Daily', 'news.example.com', 'https://news.example.com/meridian-uae-shell-supply', 'https://img.example.com/moments/9412.jpg', 12),
  (9413, 'c0ffee00-0000-4000-8000-000000000003', 'Halcyon Land Systems (TEST)', '2025-12-10', 'Ammunition', 'Poland', 'Poland, South Korea', 'Europe', 'NATO 155 Standard Qualification (TEST)', 'Halcyon K-Shell 155 qualified to NATO standard', 'K-Shell 155 clears NATO qualification.', 'Halcyon Land Systems (TEST) announced NATO qualification of K-Shell 155.', 'Halcyon Land Systems (TEST) announced that K-Shell 155 passed NATO qualification testing, opening NATO-member orders.', 'Touches Aurora Shell 155 (TEST): K-Shell becomes eligible for the same NATO orders at a similar specification.', 'high', 'Test Defence Daily', 'news.example.com', 'https://news.example.com/moment-9413', 'https://img.example.com/moments/9413.jpg', 13);
