  ('b3000000-0000-4000-8000-000000000012', 'b0000000-0000-4000-8000-000000000033', 'HR-7 rifle ordered by Egypt', 'https://news.example.com/hr-7-egypt-order', '2026-06-22', 'Test Defence Daily', 'Export', 9309, NULL, NULL, NULL),
