INSERT INTO staging.competitive_matchup
  (matchup_id, client_product_id, client_product_name, competitor_id, competitor_name, competitor_country, competitor_product_id, competitor_product_name, category_code, match_basis, verdict_headline, verdict, edge_score, decision_level, comparable_spec_count, sourced_spec_count, created_at, updated_at) VALUES
  (9301, 9101, 'Aurora Gun 155 (TEST)', 'c0ffee00-0000-4000-8000-000000000001', 'Borealis Arms (TEST)', 'Norway', 'b0000000-0000-4000-8000-000000000011', 'Borealis BH-155 Towed Howitzer (TEST)', 'Artillery', 'Same role: 155 mm towed howitzer for export artillery tenders.', 'Borealis out-fires and out-deploys the Aurora towed gun', 'BH-155 is faster into action, lighter and fires more rounds per burst. Aurora Gun 155 matches calibre and range within the margin of error and carries more ready-use rounds. Aurora needs a price or delivery argument (TEST DATA).', 10, 1, 6, 7, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9302, 9101, 'Aurora Gun 155 (TEST)', 'c0ffee00-0000-4000-8000-000000000003', 'Halcyon Land Systems (TEST)', 'South Korea', 'b0000000-0000-4000-8000-000000000031', 'Halcyon SPH-155 Self-Propelled Gun (TEST)', 'Artillery', 'Category overlap: both compete for 155 mm gun orders; different configuration (towed vs tracked self-propelled).', 'Self-propelled Halcyon wins on speed; towed Aurora wins on weight', 'SPH-155 is a tracked self-propelled gun, so weight is not like-for-like. On burst rate, crew and into-action time Halcyon leads; range is equal (TEST DATA).', 30, 1, 6, 6, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9303, 9102, 'Aurora Mounted Gun (TEST)', 'c0ffee00-0000-4000-8000-000000000001', 'Borealis Arms (TEST)', 'Norway', 'b0000000-0000-4000-8000-000000000012', 'Borealis BMG-52 Mounted Gun (TEST)', 'Artillery', 'Same role: truck-mounted 155 mm gun with 8x8 chassis.', 'Near parity: Aurora mounted gun is lighter and faster on the road', 'Calibre, range and crew match. Aurora is lighter and quicker on the road; Borealis fires faster and deploys quicker. The two split the decisive attributes (TEST DATA).', 50, 2, 7, 7, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9304, 9103, 'Aurora Shell 155 (TEST)', 'c0ffee00-0000-4000-8000-000000000001', 'Borealis Arms (TEST)', 'Norway', 'b0000000-0000-4000-8000-000000000013', 'Borealis Smart Shell 155 (TEST)', 'Ammunition', 'Same role: 155 mm extended-range artillery shell; Borealis shell is guided, Aurora is unguided base-bleed.', 'Borealis guided shell is a generation ahead on range and accuracy', 'Smart Shell 155 reaches 60 km with 8 m CEP, against 36 km and 38 m for the Aurora shell. Aurora''s shell has a longer shelf life and a far lower unit cost class (TEST DATA).', 38, 1, 5, 6, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9305, 9103, 'Aurora Shell 155 (TEST)', 'c0ffee00-0000-4000-8000-000000000003', 'Halcyon Land Systems (TEST)', 'South Korea', 'b0000000-0000-4000-8000-000000000032', 'Halcyon K-Shell 155 (TEST)', 'Ammunition', 'Same role: unguided 155 mm HE base-bleed shell for NATO-pattern guns.', 'Aurora shell is ahead on range and accuracy at similar weight', 'Aurora reaches 36 km against 32 km and shows slightly better CEP (38 m vs 40 m). Fuze, propellant and shelf life are equal; Halcyon wins on delivery lead time rather than on specification (TEST DATA).', 83, 3, 5, 6, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9306, 9103, 'Aurora Shell 155 (TEST)', 'c0ffee00-0000-4000-8000-000000000004', 'Meridian Ordnance (TEST)', 'France', 'b0000000-0000-4000-8000-000000000041', 'Meridian LR-155 Long-Range Shell (TEST)', 'Ammunition', 'Same role: 155 mm extended-range shell; Meridian shell is a long-range design with electronic fuze.', 'Meridian long-range shell clearly leads on range, accuracy and shelf life', 'LR-155 reaches 55 km with 30 m CEP and a 25-year shelf life. Aurora is behind on every comparable value; fuze types are not comparable (TEST DATA).', 12, 1, 4, 5, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9307, 9104, 'Aurora APC (TEST)', 'c0ffee00-0000-4000-8000-000000000002', 'Cobalt Dynamics (TEST)', 'United States', 'b0000000-0000-4000-8000-000000000021', 'Cobalt Guardian APC (TEST)', 'Armoured Vehicles', 'Same role: 8x8 wheeled armoured personnel carrier.', 'Cobalt Guardian carries more, runs faster and is better protected', 'Guardian leads on troops carried, speed, engine power and protection level; Aurora APC has the longer range. Protection level and weight are not scored (TEST DATA).', 30, 1, 5, 7, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9308, 9104, 'Aurora APC (TEST)', 'c0ffee00-0000-4000-8000-000000000004', 'Meridian Ordnance (TEST)', 'France', 'b0000000-0000-4000-8000-000000000042', 'Meridian W8 Wheeled APC (TEST)', 'Armoured Vehicles', 'Same role: 8x8 wheeled APC with Level 3 protection.', 'Meridian W8 holds a small edge on seats and range', 'W8 carries two more troops and drives 100 km further; top speed and protection level are equal. Aurora has the higher engine power. Meridian holds a modest edge (TEST DATA).', 38, 1, 5, 7, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9309, 9105, 'Aurora Carbine (TEST)', 'c0ffee00-0000-4000-8000-000000000003', 'Halcyon Land Systems (TEST)', 'South Korea', 'b0000000-0000-4000-8000-000000000033', 'Halcyon HR-7 Rifle (TEST)', 'Small Arms', 'Same role: 5.56 mm assault rifle for infantry.', 'HR-7 reaches further; Aurora Carbine is lighter', 'Halcyon''s rifle has the longer effective range; Aurora''s carbine is lighter. Calibre and magazine are equal and rate of fire is not judged (TEST DATA).', 50, 2, 4, 5, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9310, 9105, 'Aurora Carbine (TEST)', 'c0ffee00-0000-4000-8000-000000000005', 'Tessera Aerospace (TEST)', 'India', 'b0000000-0000-4000-8000-000000000053', 'Tessera TC-9 Carbine (TEST)', 'Small Arms', 'Same role: 5.56 mm carbine for the domestic market.', 'Split result: Aurora carbine reaches further, TC-9 is lighter', 'TC-9 is 0.2 kg lighter; Aurora''s carbine has the longer effective range (450 m vs 400 m) and an equal magazine. One win each (TEST DATA).', 50, 2, 4, 5, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9311, 9106, 'Aurora Interceptor Drone (TEST)', 'c0ffee00-0000-4000-8000-000000000005', 'Tessera Aerospace (TEST)', 'India', 'b0000000-0000-4000-8000-000000000051', 'Tessera Drone Killer (TEST)', 'Unmanned & Counter-UAS', 'Same role: radar-cued electric interceptor drone for point defence.', 'Aurora Interceptor Drone is ahead of Tessera Drone Killer', 'Aurora leads on interception range, speed, endurance and radar cue range, and carries a larger warhead. Guidance suites are similar (TEST DATA).', 90, 3, 5, 6, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00'),
  (9312, 9106, 'Aurora Interceptor Drone (TEST)', 'c0ffee00-0000-4000-8000-000000000002', 'Cobalt Dynamics (TEST)', 'United States', 'b0000000-0000-4000-8000-000000000023', 'Cobalt Swarm Interceptor (TEST)', 'Unmanned & Counter-UAS', 'Same role: counter-UAS interceptor drone; Cobalt is a larger, longer-range design.', 'Cobalt Swarm Interceptor is faster and reaches further', 'Swarm Interceptor beats the Aurora drone on range, speed and endurance. Aurora''s argument is price and local support, not performance (TEST DATA).', 12, 1, 4, 5, '2026-10-10 10:00:00+00', '2026-10-14 10:00:00+00');
