INSERT INTO staging.competitive_product_evaluation
  (evaluation_id, analytics_tab, category, kssl_product_id, kssl_product_name, competitor_product_id, competitor_product_name, competitor_name, competitor_country, comparable_value_count, sourced_value_count, compare_action_enabled, verdict, competitor_analytics, kssl_analytics) VALUES
  ('b4000000-0000-4000-8000-000000000001', 'Analytics', 'Artillery', '00000000-0000-4000-8000-000000009101', 'Aurora Gun 155 (TEST)', 'b0000000-0000-4000-8000-000000000011', 'Borealis BH-155 Towed Howitzer (TEST)', 'Borealis Arms (TEST)', 'Norway', 6, 7, true, 'BH-155 is faster into action, lighter and fires more rounds per burst. Aurora Gun 155 matches calibre and range within the margin of error and carries more ready-use rounds. Aurora needs a price or delivery argument (TEST DATA).', '{"edge_score": 10, "decision_level": 1, "wins": 4}', '{"edge_score": 10, "decision_level": 1, "wins": 0}'),
  ('b4000000-0000-4000-8000-000000000002', 'Analytics', 'Ammunition', '00000000-0000-4000-8000-000000009103', 'Aurora Shell 155 (TEST)', 'b0000000-0000-4000-8000-000000000013', 'Borealis Smart Shell 155 (TEST)', 'Borealis Arms (TEST)', 'Norway', 5, 6, true, 'Smart Shell 155 reaches 60 km with 8 m CEP, against 36 km and 38 m for the Aurora shell. Aurora''s shell has a longer shelf life and a far lower unit cost class (TEST DATA).', '{"edge_score": 38, "decision_level": 1, "wins": 2}', '{"edge_score": 38, "decision_level": 1, "wins": 1}'),
  ('b4000000-0000-4000-8000-000000000003', 'Analytics', 'Ammunition', '00000000-0000-4000-8000-000000009103', 'Aurora Shell 155 (TEST)', 'b0000000-0000-4000-8000-000000000032', 'Halcyon K-Shell 155 (TEST)', 'Halcyon Land Systems (TEST)', 'South Korea', 5, 6, true, 'Aurora reaches 36 km against 32 km and shows slightly better CEP (38 m vs 40 m). Fuze, propellant and shelf life are equal; Halcyon wins on delivery lead time rather than on specification (TEST DATA).', '{"edge_score": 83, "decision_level": 3, "wins": 0}', '{"edge_score": 83, "decision_level": 3, "wins": 2}'),
  ('b4000000-0000-4000-8000-000000000004', 'Analytics', 'Armoured Vehicles', '00000000-0000-4000-8000-000000009104', 'Aurora APC (TEST)', 'b0000000-0000-4000-8000-000000000021', 'Cobalt Guardian APC (TEST)', 'Cobalt Dynamics (TEST)', 'United States', 5, 7, true, 'Guardian leads on troops carried, speed, engine power and protection level; Aurora APC has the longer range. Protection level and weight are not scored (TEST DATA).', '{"edge_score": 30, "decision_level": 1, "wins": 3}', '{"edge_score": 30, "decision_level": 1, "wins": 1}'),
  ('b4000000-0000-4000-8000-000000000005', 'Analytics', 'Small Arms', '00000000-0000-4000-8000-000000009105', 'Aurora Carbine (TEST)', 'b0000000-0000-4000-8000-000000000033', 'Halcyon HR-7 Rifle (TEST)', 'Halcyon Land Systems (TEST)', 'South Korea', 4, 5, true, 'Halcyon''s rifle has the longer effective range; Aurora''s carbine is lighter. Calibre and magazine are equal and rate of fire is not judged (TEST DATA).', '{"edge_score": 50, "decision_level": 2, "wins": 1}', '{"edge_score": 50, "decision_level": 2, "wins": 1}'),
  ('b4000000-0000-4000-8000-000000000006', 'Analytics', 'Unmanned & Counter-UAS', '00000000-0000-4000-8000-000000009106', 'Aurora Interceptor Drone (TEST)', 'b0000000-0000-4000-8000-000000000051', 'Tessera Drone Killer (TEST)', 'Tessera Aerospace (TEST)', 'India', 5, 6, true, 'Aurora leads on interception range, speed, endurance and radar cue range, and carries a larger warhead. Guidance suites are similar (TEST DATA).', '{"edge_score": 90, "decision_level": 3, "wins": 0}', '{"edge_score": 90, "decision_level": 3, "wins": 4}');
